SELECT c.c_customer_id, CASE WHEN c.c_birth_year < 1991 THEN 'Young' WHEN c.c_birth_year BETWEEN 1991 AND 1988 THEN 'Middle' ELSE 'Old' END AS age_group, c.c_preferred_cust_flag, hd.hd_buy_potential, (c.c_birth_day + c.c_birth_month) * hd.hd_vehicle_count AS combined_metric, CASE WHEN hd.hd_income_band_sk IS NULL THEN 'Unknown' ELSE CONCAT('Band', CAST(hd.hd_income_band_sk AS VARCHAR)) END AS income_band_label, COALESCE(c.c_email_address, 'noemail@example.com') AS email FROM customer c JOIN household_demographics hd ON c.c_current_hdemo_sk = hd.hd_demo_sk WHERE c.c_customer_id <> 'AAAAAAAAGIHEGGAA'
